1	import type { AppEventMap, AppEventType } from "@motion-studio/shared";
2	import { PluginLifecycleState } from "@motion-studio/shared";
3	import type { IPlugin } from "./plugin";
4	import type { IPluginAPI } from "./plugin-api";
5	import { buildScopedPluginAPI, isKnownPluginPermission, type IPluginManifest } from "./permissions";
6	
7	/** Same generic shape as History's `IHistoryEventSink` / AI's `IAIEventSink`. */
8	export interface IPluginEventSink {
9	  emit<T extends AppEventType>(type: T, payload: AppEventMap[T]): void;
10	}
11	
12	export class UnknownPluginError extends Error {
13	  constructor(pluginId: string) {
14	    super(`PluginRegistry: no plugin registered with id "${pluginId}"`);
15	    this.name = "UnknownPluginError";
16	  }
17	}
18	
19	export class PluginIdMismatchError extends Error {
20	  constructor(pluginId: string, manifestId: string) {
21	    super(`PluginRegistry: plugin id "${pluginId}" does not match manifest id "${manifestId}"`);
22	    this.name = "PluginIdMismatchError";
23	  }
24	}
25	
26	export class UnknownPluginPermissionError extends Error {
27	  constructor(pluginId: string, permission: string) {
28	    super(`PluginRegistry: plugin "${pluginId}" requested unknown permission "${permission}"`);
29	    this.name = "UnknownPluginPermissionError";
30	  }
31	}
32	
33	export class DuplicatePluginError extends Error {
34	  constructor(pluginId: string) {
35	    super(`PluginRegistry: a plugin with id "${pluginId}" is already registered`);
36	    this.name = "DuplicatePluginError";
37	  }
38	}
39	
40	export class InvalidPluginStateTransitionError extends Error {
41	  constructor(pluginId: string, from: PluginLifecycleState, action: string) {
42	    super(`PluginRegistry: cannot ${action} plugin "${pluginId}" while in state "${from}"`);
43	    this.name = "InvalidPluginStateTransitionError";
44	  }
45	}
46	
47	interface IPluginRecord {
48	  readonly plugin: IPlugin;
49	  readonly manifest: IPluginManifest;
50	  state: PluginLifecycleState;
51	}
52	
53	export interface IPluginRegistryOptions {
54	  readonly events?: IPluginEventSink;
55	}
56	
57	/**
58	 * Registration/activation lifecycle for plugins — PLAN.md Phase 14:
59	 * "register -> activate -> suspend -> deactivate". See
60	 * `docs/16-plugin-system/lifecycle.md`.
61	 *
62	 * `suspend()`/`resume()` are registry-level bookkeeping only: `IPlugin`
63	 * declares no `suspend`/`resume` hooks (PLAN.md's `IPlugin` shape is just
64	 * `activate`/`deactivate`), so suspending a plugin doesn't call into plugin
65	 * code at all — it just marks the plugin ineligible for whatever dispatches
66	 * to `Ready` plugins, while keeping its activated instance alive for a
67	 * cheap `resume()`. This resolves `overview.md`'s open lifecycle question
68	 * in favor of the simpler option, same call `CompositeCommand` (Phase 11)
69	 * made for macro-recording granularity.
70	 */
71	export class PluginRegistry {
72	  private readonly plugins = new Map<string, IPluginRecord>();
73	  private readonly events: IPluginEventSink | undefined;
74	
75	  constructor(options: IPluginRegistryOptions = {}) {
76	    this.events = options.events;
77	  }
78	
79	  /**
80	   * `Validating` -> `RequestingPermissions` -> `Registered`. Does not call
81	   * `plugin.activate()` — that only happens in `activate()`.
82	   */
83	  register(plugin: IPlugin, manifest: IPluginManifest): void {
84	    if (plugin.id !== manifest.id) {
85	      throw new PluginIdMismatchError(plugin.id, manifest.id);
86	    }
87	    if (this.plugins.has(plugin.id)) {
88	      throw new DuplicatePluginError(plugin.id);
89	    }
90	    for (const permission of manifest.permissions) {
91	      if (!isKnownPluginPermission(permission)) {
92	        throw new UnknownPluginPermissionError(plugin.id, permission);
93	      }
94	    }
95	    this.plugins.set(plugin.id, {
96	      plugin,
97	      manifest,
98	      state: PluginLifecycleState.Registered,
99	    });
100	    this.events?.emit("PluginRegistered", { pluginId: plugin.id });
101	  }
102	
103	  /**
104	   * `Registered` -> `Initializing` -> `Ready`. Builds a permission-scoped
105	   * `IPluginAPI` from `hostApi` (the real, fully-populated API the caller
106	   * assembled from its actual engines — this package never assembles that
107	   * itself, since it never imports another engine) and calls
108	   * `plugin.activate(scopedApi)`. Reverts to `Registered` on failure so a
109	   * failed activation can be retried.
110	   */
111	  async activate(pluginId: string, hostApi: IPluginAPI): Promise<void> {
112	    const record = this.requireRecord(pluginId);
113	    if (record.state !== PluginLifecycleState.Registered) {
114	      throw new InvalidPluginStateTransitionError(pluginId, record.state, "activate");
115	    }
116	    record.state = PluginLifecycleState.Initializing;
117	    try {
118	      const scopedApi = buildScopedPluginAPI(hostApi, record.manifest.permissions);
119	      await record.plugin.activate(scopedApi);
120	      record.state = PluginLifecycleState.Ready;
121	      this.events?.emit("PluginActivated", { pluginId });
122	    } catch (error) {
123	      record.state = PluginLifecycleState.Registered;
124	      const reason = error instanceof Error ? error.message : String(error);
125	      this.events?.emit("PluginActivationFailed", { pluginId, reason });
126	      throw error;
127	    }
128	  }
129	
130	  /** `Ready` -> `Suspended`. See class doc — no plugin method is called. */
131	  suspend(pluginId: string): void {
132	    const record = this.requireRecord(pluginId);
133	    if (record.state !== PluginLifecycleState.Ready) {
134	      throw new InvalidPluginStateTransitionError(pluginId, record.state, "suspend");
135	    }
136	    record.state = PluginLifecycleState.Suspended;
137	    this.events?.emit("PluginSuspended", { pluginId });
138	  }
139	
140	  /** `Suspended` -> `Ready`. Resumes without re-running `activate()`. */
141	  resume(pluginId: string): void {
142	    const record = this.requireRecord(pluginId);
143	    if (record.state !== PluginLifecycleState.Suspended) {
144	      throw new InvalidPluginStateTransitionError(pluginId, record.state, "resume");
145	    }
146	    record.state = PluginLifecycleState.Ready;
147	    this.events?.emit("PluginActivated", { pluginId });
148	  }
149	
150	  /** `Ready` | `Suspended` -> `Deactivated` (terminal). Calls `plugin.deactivate()`. */
151	  async deactivate(pluginId: string): Promise<void> {
152	    const record = this.requireRecord(pluginId);
153	    if (
154	      record.state !== PluginLifecycleState.Ready &&
155	      record.state !== PluginLifecycleState.Suspended
156	    ) {
157	      throw new InvalidPluginStateTransitionError(pluginId, record.state, "deactivate");
158	    }
159	    await record.plugin.deactivate();
160	    record.state = PluginLifecycleState.Deactivated;
161	    this.events?.emit("PluginDeactivated", { pluginId });
162	  }
163	
164	  getState(pluginId: string): PluginLifecycleState {
165	    return this.requireRecord(pluginId).state;
166	  }
167	
168	  isRegistered(pluginId: string): boolean {
169	    return this.plugins.has(pluginId);
170	  }
171	
172	  /** Snapshot for a future plugin-management panel — id + state, oldest-registered first. */
173	  list(): readonly { readonly id: string; readonly state: PluginLifecycleState }[] {
174	    return [...this.plugins.values()].map((record) => ({
175	      id: record.plugin.id,
176	      state: record.state,
177	    }));
178	  }
179	
180	  private requireRecord(pluginId: string): IPluginRecord {
181	    const record = this.plugins.get(pluginId);
182	    if (!record) {
183	      throw new UnknownPluginError(pluginId);
184	    }
185	    return record;
186	  }
187	}
